sys_script.script:
(function executeRule(current, previous) {

     // =========================================
    //  ADMINs
    // =========================================
    if (
        gs.getUser().hasRole('admin') ||
        gs.hasRole('x_ctans_incentnow.admin') ||
        gs.hasRole('x_ctans_incentnow.org_executive')
    ) {
        return;
    }

    // =========================================
    // TERRITORY ADMIN
    // =========================================
    if (gs.hasRole('x_ctans_incentnow.territory_admin')) {

        var territoryEnabled = false;

        try {
            territoryEnabled = new IncentNowUtils().isTerritoryExtensionActive() === true;

            if (!territoryEnabled) {
                current.addEncodedQuery('sys_idISEMPTY');
                return;
            }
            new x_ctans_territory.IncentNowTerritoryResolver().applyTerritoryAdminCoreFilter(current);

        } catch (territoryError) {
            gs.error('[IncentIQ Access] Territory filter failed. ' + 'User=' + gs.getUserName() + ', error=' + territoryError.message);
            current.addEncodedQuery('sys_idISEMPTY');
        }

        return;
    }
     //All other roles
    var utils = new IncentNowAccessUtils();
    utils.applyPlanFilter(current);

})(current, previous);
